Rule.Source:
import java.text.SimpleDateFormat;
import java.util.Date;
import sailpoint.object.Identity;
import sailpoint.object.Link;
import sailpoint.tools.Util;

// WICHTIG: In BeanShell ist ein nicht gebundenes Argument "void",
// nicht null. Ein blosses (link != null) loest den Fehler selbst
// aus, weil schon das Aufloesen der undefinierten Variablen
// fehlschlaegt:
//     bsh.EvalError: ... on undefined variable or class name: link
//
// Diese Regel laeuft aus zwei Kontexten: waehrend der Aggregation
// (link gebunden) und beim Identity-Refresh ohne Account (link
// undefiniert). Deshalb erst auf void pruefen und auf eine lokale
// Variable normalisieren.
Link hrLink = null;
if (link != void && link != null) {
    hrLink = link;
}
Identity ident = null;
if (identity != void && identity != null) {
    ident = identity;
}

// Die Werte stehen am HR-Link, nicht an der Identitaet: Diese
// Regel laeuft waehrend der Attributberechnung, die Identitaet ist
// zu diesem Zeitpunkt also noch nicht vollstaendig befuellt.
//
// Link hat KEIN getStringAttribute() - nur Identity. Am Link also
// getAttribute() mit Cast (an der laufenden 8.5 geprueft).
String start = null;
String ende  = null;

if (hrLink != null) {
    start = (String) hrLink.getAttribute("startDate");
    ende  = (String) hrLink.getAttribute("endDate");
}
if (Util.isNullOrEmpty(start) && ident != null) {
    start = ident.getStringAttribute("startDate");
}
if (Util.isNullOrEmpty(ende) && ident != null) {
    ende = ident.getStringAttribute("endDate");
}

// Ohne Datumsangaben keine Aussage - dann nicht sperren.
if (Util.isNullOrEmpty(start) && Util.isNullOrEmpty(ende)) {
    return Boolean.FALSE;
}

SimpleDateFormat fmt = new SimpleDateFormat("yyyy-MM-dd");
fmt.setLenient(false);

// Auf Tagesgenauigkeit abschneiden: sonst gilt ein Austritt am
// heutigen Tag je nach Uhrzeit mal so und mal so.
java.util.Calendar cal = java.util.Calendar.getInstance();
cal.set(java.util.Calendar.HOUR_OF_DAY, 0);
cal.set(java.util.Calendar.MINUTE, 0);
cal.set(java.util.Calendar.SECOND, 0);
cal.set(java.util.Calendar.MILLISECOND, 0);
Date heute = cal.getTime();

// Eintritt steht noch bevor.
if (Util.isNotNullOrEmpty(start)) {
    try {
        Date eintritt = fmt.parse(start);
        if (eintritt.after(heute)) {
            return Boolean.TRUE;
        }
    } catch (Exception e) {
        // Unlesbares Datum nicht als Sperrgrund werten - ein
        // Tippfehler in der Quelle darf niemanden aussperren.
    }
}

// Austritt erreicht oder ueberschritten.
if (Util.isNotNullOrEmpty(ende)) {
    try {
        Date austritt = fmt.parse(ende);
        if (!austritt.after(heute)) {
            return Boolean.TRUE;
        }
    } catch (Exception e) {
        // siehe oben
    }
}

return Boolean.FALSE;

import sailpoint.object.Identity;
import sailpoint.tools.Util;

// Nicht gebundene Argumente sind in BeanShell "void", nicht null.
Identity neu = null;
if (newIdentity != void && newIdentity != null) {
    neu = newIdentity;
}
Identity alt = null;
if (previousIdentity != void && previousIdentity != null) {
    alt = previousIdentity;
}

if (neu == null) {
    return false;
}

// Der Wechsel von aktiv auf gesperrt.
boolean wurdeGesperrt = (alt == null || !alt.isInactive())
                        && neu.isInactive();
if (!wurdeGesperrt) {
    return false;
}

// Entscheidend: nur mit gesetztem Austrittsdatum ist es ein
// Austritt. Bei einem noch nicht erreichten Eintritt ist das Feld
// null.
String ende = neu.getStringAttribute("endDate");
return Util.isNotNullOrEmpty(ende);
